CREATE DATABASE IF NOT EXISTS inventory_db;
USE inventory_db;

CREATE TABLE categories (category_id INT PRIMARY KEY, category_name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(255)) ENGINE=InnoDB;
CREATE TABLE suppliers (supplier_id INT PRIMARY KEY, supplier_name VARCHAR(150) NOT NULL, contact_person VARCHAR(100), email VARCHAR(150) NOT NULL UNIQUE, phone VARCHAR(15), city VARCHAR(80), state VARCHAR(80), status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE') ENGINE=InnoDB;
CREATE TABLE warehouses (warehouse_id INT PRIMARY KEY, warehouse_name VARCHAR(120) NOT NULL UNIQUE, address VARCHAR(255), city VARCHAR(80), state VARCHAR(80), capacity_units INT NOT NULL, status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE', CHECK (capacity_units > 0)) ENGINE=InnoDB;
CREATE TABLE products (product_id INT PRIMARY KEY, sku VARCHAR(30) NOT NULL UNIQUE, product_name VARCHAR(150) NOT NULL, category_id INT NOT NULL, preferred_supplier_id INT NOT NULL, unit_cost DECIMAL(10,2) NOT NULL, selling_price DECIMAL(10,2) NOT NULL, reorder_level INT NOT NULL DEFAULT 10, unit_of_measure VARCHAR(20) DEFAULT 'PCS', status ENUM('ACTIVE','DISCONTINUED') DEFAULT 'ACTIVE', CONSTRAINT fk_product_category FOREIGN KEY(category_id) REFERENCES categories(category_id), CONSTRAINT fk_product_supplier FOREIGN KEY(preferred_supplier_id) REFERENCES suppliers(supplier_id), CHECK(unit_cost>0), CHECK(selling_price>0), CHECK(reorder_level>=0)) ENGINE=InnoDB;
CREATE TABLE purchase_orders (purchase_order_id INT PRIMARY KEY, supplier_id INT NOT NULL, warehouse_id INT NOT NULL, order_date DATE NOT NULL, expected_date DATE, status ENUM('DRAFT','APPROVED','PARTIALLY_RECEIVED','RECEIVED','CANCELLED') NOT NULL DEFAULT 'DRAFT', notes VARCHAR(255), CONSTRAINT fk_po_supplier FOREIGN KEY(supplier_id) REFERENCES suppliers(supplier_id), CONSTRAINT fk_po_warehouse FOREIGN KEY(warehouse_id) REFERENCES warehouses(warehouse_id), CHECK(expected_date IS NULL OR expected_date>=order_date)) ENGINE=InnoDB;
CREATE TABLE purchase_order_items (purchase_order_item_id INT PRIMARY KEY, purchase_order_id INT NOT NULL, product_id INT NOT NULL, quantity_ordered INT NOT NULL, quantity_received INT NOT NULL DEFAULT 0, unit_cost DECIMAL(10,2) NOT NULL, CONSTRAINT fk_poi_purchase_order FOREIGN KEY(purchase_order_id) REFERENCES purchase_orders(purchase_order_id), CONSTRAINT fk_poi_product FOREIGN KEY(product_id) REFERENCES products(product_id), CHECK(quantity_ordered>0), CHECK(quantity_received>=0 AND quantity_received<=quantity_ordered), CHECK(unit_cost>0)) ENGINE=InnoDB;
CREATE TABLE warehouse_stock (product_id INT NOT NULL, warehouse_id INT NOT NULL, quantity_on_hand INT NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(product_id,warehouse_id), CONSTRAINT fk_ws_product FOREIGN KEY(product_id) REFERENCES products(product_id), CONSTRAINT fk_ws_warehouse FOREIGN KEY(warehouse_id) REFERENCES warehouses(warehouse_id), CHECK(quantity_on_hand>=0)) ENGINE=InnoDB;
CREATE TABLE stock_movements (movement_id INT PRIMARY KEY, product_id INT NOT NULL, warehouse_id INT NOT NULL, movement_type ENUM('IN','OUT') NOT NULL, quantity INT NOT NULL, unit_cost DECIMAL(10,2) NOT NULL, movement_date DATE NOT NULL, reference_type VARCHAR(30), reference_id INT, remarks VARCHAR(255), CONSTRAINT fk_sm_product FOREIGN KEY(product_id) REFERENCES products(product_id), CONSTRAINT fk_sm_warehouse FOREIGN KEY(warehouse_id) REFERENCES warehouses(warehouse_id), CHECK(quantity>0), CHECK(unit_cost>0)) ENGINE=InnoDB;
